'use strict';
// Design review only: no network requests, authentication, or production writes.
const $ = (s, root = document) => root.querySelector(s);
const esc = v => String(v ?? '').replace(/[&<>"']/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const t = (en, ar) => state.lang === 'ar' ? ar : en;
const paths = {
  home:'M3 10 12 3l9 7M5 9v12h14V9M9 21v-7h6v7',
  check:'M9 5H5v16h14V5h-4M9 3h6v4H9zM8 13l3 3 5-6',
  people:'M16 21v-2a4 4 0 0 0-4-4H6a4 4 0 0 0-4 4v2M9 11a4 4 0 1 0 0-8 4 4 0 0 0 0 8M17 4a4 4 0 0 1 0 8M22 21v-2a4 4 0 0 0-3-4',
  truck:'M1 5h13v12H1zM14 9h4l4 5v3h-8M5 21a2 2 0 1 0 0-4 2 2 0 0 0 0 4M18 21a2 2 0 1 0 0-4 2 2 0 0 0 0 4',
  calc:'M5 2h14v20H5zM8 5h8v4H8zM8 13h1M15 13h1M8 17h1M15 17h1',
  layers:'m12 3 10 6-10 6L2 9zM2 13l10 6 10-6M2 17l10 6 10-6',
  clock:'M12 8v5l3 2M22 12a10 10 0 1 1-20 0 10 10 0 0 1 20 0',
  file:'M14 2H4v20h16V8zM14 2v6h6M8 12h8M8 16h8',
  arrow:'M4 12h16M14 6l6 6-6 6',
  box:'m12 3 9 5v10l-9 5-9-5V8zM3 8l9 5 9-5M12 13v10',
  menu:'M4 6h16M4 12h16M4 18h16'
};
const icon = name => `<svg class="icon" viewBox="0 0 24 24" aria-hidden="true"><path d="${paths[name] || paths.file}"/></svg>`;
const roles = {
  employee:['Employee','موظف'], manager:['Department manager','مدير إدارة'], hr:['HR recruiter','مسؤول توظيف'],
  sector:['Sector approver','معتمد القطاع'], operations:['Delivery operations','عمليات التوصيل'],
  estimator:['Cost engineer','مهندس تكاليف'], executive:['Executive overview','الإدارة التنفيذية']
};
const roleName = (r = state.role) => t(...roles[r]);
const pageNames = {home:['Overview','نظرة عامة'], approvals:['My approvals','اعتماداتي'], hr:['People & HR','الموارد البشرية'], delivery:['Delivery','التوصيل'], estimator:['Cost estimator','تقدير التكلفة'], architecture:['Architecture & plan','المعمارية والخطة']};
const baseRequests = () => [
  {id:'HR-104', title:['Production operator','عامل إنتاج'], owner:'employee', a:2,b:1,exception:false,stage:'manager',note:'',events:[['Request submitted · 3 positions reserved','تم إرسال الطلب · حجز ٣ وظائف']]},
  {id:'HR-103', title:['Assembly technician','فني تجميع'], owner:'manager',a:1,b:0,exception:false,stage:'hr',note:'',events:[['Department step skipped: requester is the manager','تخطي اعتماد الإدارة لأن مقدم الطلب هو المدير']]},
  {id:'HR-102', title:['Maintenance technician','فني صيانة'], owner:'manager',a:5,b:0,exception:true,stage:'sector',note:'Demo expansion request',events:[['Justified capacity exception submitted','تم إرسال طلب استثناء عدد بمبرر']]}
];
const initialState = () => ({lang:'en',role:'manager',page:'home',filter:'all',requests:baseRequests(),deliveryStep:2,deliveryNote:'',deliveryOutcome:'',estimateReviewed:false,estimateSaved:null,estimate:{qty:12,rate:280,waste:10,accessoryQty:8,accessoryRate:75,labor:650,outside:400,overhead:8}});
let state = initialState();
let toastTimer;
function toast(message){clearTimeout(toastTimer);$('#toast').textContent=message;$('#toast').classList.add('show');toastTimer=setTimeout(()=>$('#toast').classList.remove('show'),4500);}
const badge = (text, color='') => `<span class="pill ${color}">${esc(text)}</span>`;
const button = (label, action, attrs='', cls='') => `<button class="${cls}" data-action="${action}" ${attrs}>${label}</button>`;
const pageTitle = page => t(...pageNames[page]);
function allowedPages(){
  const base=['home'];
  if(['employee','manager','hr','sector'].includes(state.role))base.push('approvals','hr');
  if(state.role==='executive')base.push('hr','delivery','estimator');
  if(state.role==='operations')base.push('delivery');
  if(state.role==='estimator')base.push('estimator');
  return [...base,'architecture'];
}
function visibleRequests(){
  if(state.role==='employee')return state.requests.filter(r=>r.owner==='employee');
  if(state.role==='sector')return state.requests.filter(r=>r.exception);
  if(state.role==='manager'||state.role==='hr')return state.requests;
  return []; // Executives see aggregates; no automatic candidate/request access.
}
function actionable(){return state.requests.filter(r=>r.stage===state.role&&r.owner!==state.role);}
function reqTitle(r){return Array.isArray(r.title)?t(...r.title):r.title;}
function reqStatus(r){return r.stage==='approved'?t('Approved','معتمد'):r.stage==='rejected'?t('Rejected','مرفوض'):t('Awaiting ','بانتظار ')+roleName(r.stage);}
function heading(kicker,title,subtitle,actions=''){return `<div class="page-heading"><div><div class="eyebrow">${kicker}</div><h1>${title}</h1><p>${subtitle}</p></div>${actions?`<div class="heading-action">${actions}</div>`:''}</div>`;}
function stats(items){return `<div class="stats">${items.map(([label,value,hint,i])=>`<div class="stat"><div class="label">${label}${icon(i)}</div><div class="value">${value}</div><div class="hint">${hint}</div></div>`).join('')}</div>`;}
function panel(title,sub,body,action=''){return `<section class="panel"><div class="panel-head"><div><h2>${title}</h2>${sub?`<p>${sub}</p>`:''}</div>${action}</div>${body}</section>`;}
function requestRows(list){
  if(!list.length)return `<div class="empty"><h3>${t('You are up to date','لا توجد اعتمادات حالياً')}</h3><p>${t('There are no matching requests for this view.','لا توجد طلبات مطابقة لهذه الصفحة.')}</p></div>`;
  return `<div class="table-wrap"><table class="requests"><thead><tr><th>${t('Request','الطلب')}</th><th>${t('Positions','العدد')}</th><th>${t('Next step','الخطوة التالية')}</th><th>${t('Action','الإجراء')}</th></tr></thead><tbody>${list.map(r=>`<tr><td><strong>${esc(reqTitle(r))}</strong><span class="sub mono">${r.id} · ${t('Sample','مثال')}</span></td><td>${r.a+r.b}<span class="sub">${r.a&&r.b?t('2 locations','موقعان'):t('1 location','موقع واحد')}</span></td><td>${badge(reqStatus(r),r.stage==='approved'?'':r.stage==='rejected'?'red':'amber')}</td><td>${button(t('Review','عرض'),'request',`data-id="${r.id}"`)}</td></tr>`).join('')}</tbody></table></div>`;
}
function navTo(page){if(!allowedPages().includes(page))return;state.page=page;state.filter='all';render();window.scrollTo(0,0);$('#main').focus({preventScroll:true});}
function render(){
  if(!allowedPages().includes(state.page))state.page='home';
  document.documentElement.lang=state.lang;document.documentElement.dir=state.lang==='ar'?'rtl':'ltr';
  document.body.dir=document.documentElement.dir;document.body.classList.remove('menu-open');
  const navIcons={home:'home',approvals:'check',hr:'people',delivery:'truck',estimator:'calc',architecture:'layers'};
  $('#sidebar').innerHTML=`<div class="brand"><span class="brand-mark">K</span><div><strong lang="ar">قنديل</strong><small>COMPANY WORKSPACE</small></div></div><div class="nav-label">${t('YOUR WORKSPACE','مساحة العمل')}</div><nav class="nav" aria-label="${t('Main navigation','القائمة الرئيسية')}">${allowedPages().map(p=>button(`${icon(navIcons[p])}<span>${pageTitle(p)}</span>${p==='approvals'?`<span class="count">${actionable().length}</span>`:''}`,'nav',`data-page="${p}" ${p===state.page?'aria-current="page"':''}`,p===state.page?'active':'')).join('')}</nav><div class="sidebar-bottom"><strong>${t('One place. Connected teams.','مكان واحد. إدارات متصلة.')}</strong>${t('HR · Operations · Engineering','موارد بشرية · عمليات · هندسة')}<br><a href="../Platform_Blueprint.html">${t('Read the blueprint ↗','قراءة مخطط المنصة ↗')}</a></div>`;
  if(!$('.mobile-shade')){const shade=document.createElement('div');shade.className='mobile-shade';shade.dataset.action='menu';document.body.appendChild(shade);}
  $('#topbar').innerHTML=`${button(icon('menu'),'menu',`aria-label="${t('Toggle navigation','فتح القائمة')}"`,'mobile-menu')}<div class="crumb">${t('Kandil workspace','مساحة عمل قنديل')}<span>/</span><b>${pageTitle(state.page)}</b></div><div class="toolbar"><label for="role">${t('Preview as','عرض بدور')}</label><select id="role" aria-label="${t('Preview role','دور العرض')}">${Object.entries(roles).map(([k,v])=>`<option value="${k}" ${k===state.role?'selected':''}>${t(...v)}</option>`).join('')}</select>${button(state.lang==='en'?'العربية':'English','language',`aria-label="${t('Switch to Arabic','التبديل إلى الإنجليزية')}"`)}<div class="avatar" aria-hidden="true">${state.role.slice(0,2).toUpperCase()}</div></div>`;
  $('#reviewbar').innerHTML=`<span>${t('DESIGN PREVIEW · Synthetic data · All actions stay in this tab','معاينة التصميم · بيانات تجريبية · جميع الإجراءات داخل هذه الصفحة فقط')}</span>${button(t('Reset demo','إعادة التجربة'),'reset')}`;
  $('#main').innerHTML=({home,approvals,hr,delivery,estimator,architecture})[state.page]();
  $('#footer').innerHTML=`<span>قنديل · ${t('Platform design 01 · 11 October 2026','تصميم المنصة 01 · 11 أكتوبر 2026')}</span><span>${t('Local prototype · Connections and sign-in are not implemented','نموذج محلي · الربط وتسجيل الدخول غير منفذين')}</span>`;
}
function moduleCard(page,ic,title,desc,tag){return button(`<div class="row">${icon(ic)}${badge(tag,'grey')}</div><h3>${title}</h3><p>${desc}</p>`,'nav',`data-page="${page}"`,'module-card');}
function home(){
  const isOps=state.role==='operations',isEng=state.role==='estimator',isExec=state.role==='executive',isEmp=state.role==='employee';
  const target=isOps?'delivery':isEng?'estimator':isExec?'architecture':'approvals';
  const pending=actionable().length;
  const intro=isEmp?t('Your working day, in one place.','خدماتك اليومية في مكان واحد.'):isOps?t('Keep every delivery moving.','تابع كل رحلة توصيل.'):isEng?t('From reviewed quantities to a clear cost.','من كميات معتمدة إلى تكلفة واضحة.'):isExec?t('A connected view of the company.','رؤية متصلة لأعمال الشركة.'):t('Good morning. Let’s move work forward.','صباح الخير. نبدأ بأولويات اليوم.');
  let metrics;
  if(isOps)metrics=[[t('Sample deliveries','شحنات تجريبية'),3,t('In this design scenario','في سيناريو التصميم'),'truck'],[t('Needs attention','تحتاج متابعة'),1,t('One delayed handover','تأخير في التسليم'),'clock'],[t('Proof awaiting review','إثبات بانتظار المراجعة'),state.deliveryStep===3?1:0,t('No automatic stock update','لا تحديث آلي للمخزون'),'file'],[t('Odoo connection','ربط Odoo'),'—',t('Not connected','غير متصل'),'layers']];
  else if(isEng)metrics=[[t('Sample estimates','تقديرات تجريبية'),1,t('Editable demonstration','تجربة قابلة للتعديل'),'calc'],[t('Quantity review','مراجعة الكميات'),state.estimateReviewed?'✓':'—',t('Engineer confirmation required','يتطلب تأكيد المهندس'),'check'],[t('Rate source','مصدر الأسعار'),'—',t('Illustrative rates only','أسعار توضيحية فقط'),'file'],[t('Saved revisions','النسخ المحفوظة'),state.estimateSaved?1:0,t('In this tab only','داخل الصفحة فقط'),'layers']];
  else if(isExec)metrics=[[t('Recruitment requests','طلبات التوظيف'),state.requests.length,t('Synthetic aggregate','إجمالي تجريبي'),'people'],[t('Sample deliveries','شحنات تجريبية'),3,t('No live operations feed','لا ربط مباشر بالعمليات'),'truck'],[t('Estimator concepts','نماذج تقدير التكلفة'),1,t('Awaiting engineering review','بانتظار المراجعة الهندسية'),'calc'],[t('Live integrations','تكاملات فعلية'),0,t('Design stage','مرحلة التصميم'),'layers']];
  else metrics=[[t('For your decision','بانتظار قرارك'),pending,t('Assigned to this demo role','مسندة لدور العرض الحالي'),'check'],[t('Visible requests','الطلبات المتاحة'),visibleRequests().length,t('Within your sample scope','ضمن نطاق العرض التجريبي'),'people'],[t('Approved requests','طلبات معتمدة'),visibleRequests().filter(r=>r.stage==='approved').length,t('Offer is not actual joining','العرض لا يعني المباشرة'),'file'],[t('Live integrations','تكاملات فعلية'),0,t('This is a design preview','هذه معاينة تصميم'),'layers']];
  const hero=`<section class="hero"><div class="hero-copy"><div class="eyebrow">${t('A WORKSPACE BUILT AROUND YOUR DAY','مساحة عمل مصممة ليومك')}</div><h2>${isExec?t('One company experience.<br>Clear ownership behind it.','تجربة واحدة للشركة.<br>ومسؤولية واضحة لكل نظام.'):isEmp?t('Less chasing.<br>More clarity on every request.','متابعة أسهل.<br>وحالة واضحة لكل طلب.'):isOps?t('See the next stop.<br>Resolve the next exception.','تابع المحطة التالية.<br>وعالج الاستثناء التالي.'):isEng?t('Understand every component.<br>Explain every number.','راجع كل مكوّن.<br>واعرف مصدر كل رقم.'):t('The right task.<br>The right person. The next step.','المهمة المناسبة.<br>للشخص المناسب. والخطوة واضحة.')}</h2><p>${t('One portal connects people, delivery and engineering while Odoo keeps its agreed responsibilities.','بوابة واحدة تربط الموارد البشرية والتوصيل والهندسة، مع استمرار Odoo في مسؤولياته المتفق عليها.')}</p>${button(t('Open ','فتح ')+pageTitle(target),'nav',`data-page="${target}"`)}</div><div class="hero-art" aria-hidden="true"><div class="orbit"><div>${icon('home')} KANDIL WORKSPACE</div><div>${icon('people')} ${t('People','الموظفون')}</div><div>${icon('truck')} ${t('Delivery','التوصيل')}</div><div>${icon('calc')} ${t('Engineering','الهندسة')}</div><div>${icon('layers')} Odoo</div></div></div></section>`;
  const next= isOps?panel(t('Delivery queue','قائمة التوصيل'),t('Demonstration route','رحلة توضيحية'),deliveryList()):isEng?panel(t('Current estimate','التقدير الحالي'),t('Material quantities first','الكميات أولاً'),`<div class="panel-body"><h3>${t('Wall light · engineering sample','وحدة إضاءة حائط · مثال هندسي')}</h3><p class="muted small">${t('Review material quantities, waste convention and rate sources before freezing the cost.','راجع كميات الخامات وقاعدة الهالك ومصادر الأسعار قبل تثبيت التكلفة.')}</p><div class="form-actions">${button(t('Open estimate','فتح التقدير'),'nav','data-page="estimator"','primary')}</div></div>`):isExec?panel(t('Department readiness','جاهزية الإدارات'),t('Design and pilot status','حالة التصميم والتجربة'),`<div class="list-row"><div><h3>${t('HR recruitment','توظيف الموارد البشرية')}</h3><p>${t('Technical pilot completed; business acceptance pending','اكتملت التجربة التقنية؛ القبول التشغيلي معلق')}</p></div>${badge(t('Review','مراجعة'),'amber')}</div><div class="list-row"><div><h3>${t('Delivery & estimator','التوصيل وتقدير التكلفة')}</h3><p>${t('Concept workflows need departmental confirmation','المسارات المقترحة تحتاج تأكيد الإدارات')}</p></div>${badge(t('Design','تصميم'),'grey')}</div>`):panel(t('Your work queue','قائمة عملك'),t('Open a request to review its next step','افتح الطلب لعرض الخطوة التالية'),requestRows(isEmp?visibleRequests():actionable()));
  const insight=panel(t('The next milestone','المحطة التالية'),t('A focused first release','إصدار أول محدد'),`<div class="panel-body"><div class="eyebrow">01 / ${t('RECRUITMENT','التوظيف')}</div><h2>${t('From request to actual joining.','من طلب التوظيف إلى المباشرة.')}</h2><p class="muted small" style="margin-top:12px">${t('Agree the HR rules, connect one real workflow, then extend the portal to delivery and costing.','نتفق على قواعد الموارد البشرية، ونربط مساراً فعلياً كاملاً، ثم نوسع البوابة للتوصيل والتكلفة.')}</p><div class="note">${t('The pilot is technical evidence. HR acceptance and production readiness are still pending.','التجربة دليل تقني. موافقة HR وجاهزية الإنتاج ما زالتا معلقتين.')}</div>${button(t('Explore the architecture →','استعرض المعمارية ←'),'nav','data-page="architecture"','link')}</div>`);
  const cards=[];
  if(allowedPages().includes('hr'))cards.push(moduleCard('hr','people',t('People & HR','الموارد البشرية'),t('Requests, approvals and recruitment.','الطلبات والاعتمادات والتوظيف.'),t('HR foundation','أساس الموارد البشرية')));
  if(allowedPages().includes('delivery'))cards.push(moduleCard('delivery','truck',t('Delivery operations','عمليات التوصيل'),t('Handover, milestones and exceptions.','التسليم والمراحل والاستثناءات.'),t('Proposed module','وحدة مقترحة')));
  if(allowedPages().includes('estimator'))cards.push(moduleCard('estimator','calc',t('Cost engineering','هندسة التكاليف'),t('Reviewed quantities and traceable costs.','كميات مراجعة وتكاليف موثقة.'),t('Proposed module','وحدة مقترحة')));
  return heading(t('YOUR DAY AT KANDIL','يومك في قنديل'),intro,roleName()+t(' · Demo workspace',' · مساحة عمل تجريبية'))+hero+stats(metrics)+`<div class="grid">${next}${insight}</div>${cards.length>1?`<div class="cards">${cards.join('')}</div>`:''}`;
}
function approvals(){
  const list=state.filter==='all'?actionable():visibleRequests().filter(r=>['approved','rejected'].includes(r.stage));
  return heading(t('DECISIONS, WITH CONTEXT','قرارات بمعلومات واضحة'),pageTitle('approvals'),t('Review the request, its location quantities and the authority behind the next decision.','راجع الطلب وكميات المواقع والصلاحية المطلوبة للقرار التالي.'))+`<div class="tabs">${button(t('Needs my decision','بانتظار قراري'),'filter','data-value="all"',state.filter==='all'?'selected':'')}${button(t('Completed in my scope','المكتمل ضمن نطاقي'),'filter','data-value="done"',state.filter==='done'?'selected':'')}</div>`+panel(t('Recruitment approvals','اعتمادات التوظيف'),t('Decisions will belong to Frappe HR; the portal provides the shared inbox.','قرارات التوظيف ستكون داخل Frappe HR؛ البوابة تعرض صندوق الاعتمادات الموحد.'),requestRows(list))+`<div class="note">${t('Preview role switching shows the sequence. In production, the server must verify the real signed-in user and their current authority.','تبديل الدور هنا يوضح تسلسل الاعتماد. في النظام الفعلي يتحقق الخادم من هوية المستخدم وصلاحيته الحالية.')}</div>`;
}
function hr(){
  const canCreate=['employee','manager'].includes(state.role);
  let body=heading(t('PEOPLE / RECRUITMENT','الأفراد / التوظيف'),t('People & HR','الموارد البشرية'),t('A simple front door for employees and managers. Frappe remains the HR system behind it.','واجهة بسيطة للموظف والمدير، مع بقاء Frappe نظام الموارد البشرية الأساسي.'),canCreate?button('+ '+t('Hiring request','طلب توظيف'),'new-request','','primary'):'');
  if(state.role==='executive')return body+stats([[t('Sample requests','طلبات تجريبية'),state.requests.length,t('Aggregate only','عرض إجمالي فقط'),'people'],[t('Approved','معتمد'),state.requests.filter(r=>r.stage==='approved').length,t('Not joined headcount','لا يساوي عدد المباشرين'),'check'],[t('Exception requests','طلبات الاستثناء'),state.requests.filter(r=>r.exception).length,t('Subject to HR policy','وفق سياسة الموارد البشرية'),'clock'],[t('HR acceptance','موافقة HR'),'—',t('Pending human review','بانتظار مراجعة الفريق'),'file']])+`<div class="note">${t('Executive access is an aggregate view here. Salary, candidates and personal documents are not automatically included.','تعرض الإدارة هنا بيانات إجمالية. الرواتب والمرشحون والمستندات الشخصية لا تُتاح تلقائياً.')}</div>`;
  body+=panel(t('Recruitment requests','طلبات التوظيف'),t('Sample records · Factory A and Factory B are fictional sites','بيانات تجريبية · المصنع أ والمصنع ب مواقع افتراضية'),requestRows(visibleRequests()));
  if(state.role==='employee')body+=`<div class="cards">${button(`${icon('file')}<h3>${t('Employment letter','خطاب جهة العمل')}</h3><p>${t('Preview a sample with today’s generation date.','اعرض نموذجاً بتاريخ الإصدار اليوم.')}</p>`,'letter','','module-card')}</div>`;
  if(state.role==='hr')body+=`<div class="grid equal" style="margin-top:20px">${panel(t('Recruiter administration','إدارة التوظيف'),t('Retain native Frappe screens initially','نحتفظ بشاشات Frappe الإدارية مبدئياً'),`<div class="panel-body"><p class="small muted">${t('Candidates → interviews → accepted offers → actual joining. A candidate without email must remain supported.','المرشحون ← المقابلات ← العروض المقبولة ← المباشرة الفعلية. يجب دعم المرشح بدون بريد إلكتروني.')}</p><div class="intro-links"><a href="http://localhost:8101/kandil-pilot" target="_blank" rel="noopener">${t('Open separate local HR pilot ↗','فتح تجربة HR المحلية المنفصلة ↗')}</a></div><p class="small muted">${t('Requires the local pilot server and a separate login. This prototype sends no data to it.','يتطلب تشغيل خادم التجربة وتسجيل دخول منفصل. هذا النموذج لا يرسل بيانات إليه.')}</p></div>`)}${panel(t('Before real employee data','قبل بيانات الموظفين الفعلية'),t('Business acceptance still required','القبول التشغيلي ما زال مطلوباً'),`<div class="panel-body"><p class="small muted">${t('Confirm the route, quantity amendments, shared-phone policy, joining corrections and field-level privacy.','أكد مسار الاعتماد وتعديل العدد وسياسة الهاتف المشترك وتصحيح المباشرة وخصوصية الحقول.')}</p><div class="intro-links"><a href="../../Frappe_HR_Pilot_2026-10-11/HR_Review_Checklist_AR_EN.md">${t('HR acceptance checklist ↗','قائمة مراجعة HR ↗')}</a></div></div>`)}</div>`;
  return body+`<div class="note">${t('No offer approval creates an employee. The confirmed joining action is the point that changes occupied headcount.','اعتماد العرض لا ينشئ موظفاً. تأكيد المباشرة هو الإجراء الذي يغير عدد العاملين الفعلي.')}</div>`;
}
function deliveryList(){return `<div class="list-row"><div class="list-left"><div class="tile-icon">${icon('truck')}</div><div><h3>${t('DL-028 · Cairo handover','DL-028 · تسليم القاهرة')}</h3><p>${t('Order SO-DEMO-028 · 8 packages','طلب SO-DEMO-028 · ٨ طرود')}</p></div></div>${button(t('View','عرض'),'delivery-detail')}</div><div class="list-row"><div class="list-left"><div class="tile-icon amber">${icon('clock')}</div><div><h3>${t('DL-027 · Delivery exception','DL-027 · استثناء توصيل')}</h3><p>${t('Receiver unavailable · needs rescheduling','المستلم غير متاح · يحتاج إعادة جدولة')}</p></div></div>${badge(t('Needs attention','تحتاج متابعة'),'amber')}</div><div class="list-row"><div class="list-left"><div class="tile-icon">${icon('check')}</div><div><h3>${t('DL-026 · Completed','DL-026 · مكتمل')}</h3><p>${t('Sample proof reviewed','تمت مراجعة الإثبات التجريبي')}</p></div></div>${badge(t('Closed','مغلق'))}</div>`;}
function delivery(){return heading(t('OPERATIONS / DELIVERY','العمليات / التوصيل'),t('Every handover, accounted for.','كل تسليم موثّق.'),t('Follow operational milestones and resolve exceptions. This view does not represent live GPS or connected Odoo orders.','تابع مراحل التشغيل وعالج الاستثناءات. هذا العرض لا يمثل GPS مباشر أو أوامر مرتبطة بـ Odoo.'))+stats([[t('Sample deliveries','الشحنات التجريبية'),3,t('Illustrative queue','قائمة توضيحية'),'truck'],[t('Active handover','تسليم جارٍ'),state.deliveryStep<4?1:0,t('DL-028','DL-028'),'box'],[t('Exceptions','استثناءات'),state.deliveryOutcome?2:1,t('Require operations follow-up','تحتاج متابعة العمليات'),'clock'],[t('Odoo sync','مزامنة Odoo'),'—',t('Not connected','غير متصل'),'layers']])+`<div class="grid">${panel(t('Delivery queue','قائمة التوصيل'),t('One interactive example, two context records','مثال تفاعلي وسجلان لتوضيح السياق'),deliveryList())}${panel(t('Operational ownership','مسؤولية العمليات'),t('Delivery events are a custom module','أحداث التوصيل وحدة مخصصة'),`<div class="panel-body"><h3>${t('Proof first. Review next.','الإثبات أولاً، ثم المراجعة.')}</h3><p class="small muted" style="margin-top:12px">${t('Capture the outcome, receiver and proof. Only an authorized review should trigger an agreed Odoo action.','سجّل النتيجة والمستلم والإثبات. المراجعة المخولة فقط هي التي تطلق الإجراء المتفق عليه في Odoo.')}</p><div class="note amber">${t('Partial deliveries, returns and offline behavior need an operations workshop before implementation.','التسليم الجزئي والمرتجعات والعمل دون اتصال تحتاج جلسة مع العمليات قبل التنفيذ.')}</div></div>`)}</div>`;}
function costs(){const e=state.estimate;const material=e.qty*(1+e.waste/100)*e.rate;const accessories=e.accessoryQty*e.accessoryRate;const direct=material+accessories+e.labor+e.outside;return {material,accessories,direct,overhead:direct*e.overhead/100,total:direct*(1+e.overhead/100)};}
const money=v=>new Intl.NumberFormat(state.lang==='ar'?'ar-EG':'en-GB',{minimumFractionDigits:2,maximumFractionDigits:2}).format(v);
function estimator(){const e=state.estimate,c=costs();const edit=state.role==='estimator';return heading(t('ENGINEERING / COSTING','الهندسة / التكلفة'),t('Build the cost from the components.','ابنِ التكلفة من المكونات.'),t('Wall light · illustrative material takeoff. Review quantities and rates before making a commercial decision.','وحدة إضاءة حائط · حصر خامات توضيحي. راجع الكميات والأسعار قبل أي قرار تجاري.'))+`<div class="timeline">${[[t('Brief','المتطلبات'),true],[t('Engineering','الهندسة'),true],[t('Quantity review','مراجعة الكميات'),state.estimateReviewed],[t('Cost snapshot','نسخة التكلفة'),!!state.estimateSaved]].map(([label,done],i)=>`<div class="step ${done?'done':'current'}"><div class="dot">${done?'✓':i+1}</div><span>${label}</span></div>`).join('')}</div><div class="note amber">${t('Demo convention: net quantity × (1 + waste allowance) × rate. Not CAD extraction, cutting optimization or an approved Kandil costing policy.','قاعدة التجربة: صافي الكمية × (١ + نسبة الهالك) × السعر. ليست استخراجاً من CAD أو تحسين قص أو سياسة تكلفة معتمدة لقنديل.')}</div><form id="estimate-form"><div class="grid"><section class="panel"><div class="panel-head"><div><h2>${t('Material takeoff','حصر الخامات')}</h2><p>${t('EGP · synthetic rates · sample revision 01','جنيه مصري · أسعار تجريبية · نسخة توضيحية 01')}</p></div>${badge(state.estimateReviewed?t('Reviewed in demo','تمت مراجعة المثال'):t('Needs review','تحتاج مراجعة'),state.estimateReviewed?'':'amber')}</div><div class="table-wrap"><table class="cost-table"><thead><tr><th>${t('Component','المكوّن')}</th><th>${t('Net qty','صافي الكمية')}</th><th>${t('EGP / unit','جنيه / وحدة')}</th><th>${t('Waste %','هالك ٪')}</th></tr></thead><tbody><tr><td><strong>${t('Sheet material','خامة ألواح')}</strong><span class="sub">${t('kg · engineer-entered','كجم · إدخال المهندس')}</span></td><td><input class="cost-input" aria-label="${t('Material quantity','كمية الخامة')}" name="qty" type="number" min="0.01" max="1000000" step="0.01" value="${e.qty}" required ${edit?'':'disabled'}></td><td><input class="cost-input" aria-label="${t('Material rate','سعر الخامة')}" name="rate" type="number" min="0" max="1000000" step="0.01" value="${e.rate}" required ${edit?'':'disabled'}></td><td><input class="cost-input" aria-label="${t('Waste allowance','نسبة الهالك')}" name="waste" type="number" min="0" max="100" step="0.1" value="${e.waste}" required ${edit?'':'disabled'}></td></tr><tr><td><strong>${t('Accessories','إكسسوارات')}</strong><span class="sub">${t('piece · purchased','قطعة · مشتراة')}</span></td><td>${e.accessoryQty}</td><td>${money(e.accessoryRate)}</td><td>0</td></tr></tbody></table></div><div class="panel-body"><div class="field-grid"><label class="field">${t('Labor · EGP','العمالة · جنيه')}<input name="labor" type="number" min="0" max="10000000" step="0.01" value="${e.labor}" required ${edit?'':'disabled'}></label><label class="field">${t('Outside processing · EGP','تشغيل خارجي · جنيه')}<input name="outside" type="number" min="0" max="10000000" step="0.01" value="${e.outside}" required ${edit?'':'disabled'}></label><label class="field">${t('Overhead %','المصاريف العامة ٪')}<input name="overhead" type="number" min="0" max="100" step="0.1" value="${e.overhead}" required ${edit?'':'disabled'}><small>${t('Applied to materials + accessories + labor + outside processing in this demo.','تطبق على الخامات والإكسسوارات والعمالة والتشغيل الخارجي في المثال.')}</small></label></div>${edit?`<div class="form-actions"><button type="submit" class="primary">${t('Recalculate & reset review','إعادة الحساب وإلغاء المراجعة')}</button></div>`:''}</div></section><div><div class="cost-total"><div class="eyebrow">${t('ILLUSTRATIVE COST · EGP','تكلفة توضيحية · جنيه')}</div><strong id="cost-total">${money(c.total)}</strong><p>${t('Excludes profit, tax and unspecified electrical scope. Not a customer quote.','لا يشمل الربح أو الضريبة أو الكهرباء غير المحددة. ليس عرض سعر للعميل.')}</p></div><div class="cost-breakdown">${[[t('Materials incl. waste','خامات شاملة الهالك'),c.material],[t('Accessories','إكسسوارات'),c.accessories],[t('Labor + outside work','عمالة وتشغيل خارجي'),e.labor+e.outside],[t('Overhead','مصاريف عامة'),c.overhead]].map(([label,n])=>`<div class="cost-line"><span>${label}</span><strong>${money(n)}</strong></div>`).join('')}</div>${edit?`<div class="stack" style="margin-top:20px">${button(t('Confirm quantity & rate review','تأكيد مراجعة الكميات والأسعار'),'review-estimate','type="button"',state.estimateReviewed?'':'primary')}${button(t('Freeze demo snapshot','تثبيت نسخة تجريبية'),'save-estimate',`type="button" ${state.estimateReviewed?'':'disabled'}`)}</div>`:''}${state.estimateSaved?`<div class="note">${t('Saved snapshot','النسخة المحفوظة')}: ${money(state.estimateSaved.total)} EGP<br><small>${t('Fixed in this tab; changing inputs does not rewrite this snapshot.','مثبتة داخل الصفحة؛ تغيير المدخلات لا يعدل هذه النسخة.')}</small></div>`:''}</div></div></form>`;}
function architecture(){return heading(t('DESIGN REVIEW / BLUEPRINT','مراجعة التصميم / مخطط المنصة'),t('One front door. Clear responsibilities.','بوابة واحدة. ومسؤوليات واضحة.'),t('A custom company portal beside Odoo. Frappe powers HR only. This architecture is proposed, not deployed.','بوابة مخصصة للشركة بجانب Odoo. Frappe مسؤول عن HR فقط. هذه معمارية مقترحة وليست منشورة.'))+`<div class="intro-links"><a href="../Platform_Blueprint.html">${t('Full blueprint AR / EN ↗','المخطط التفصيلي عربي / إنجليزي ↗')}</a><a href="../../Frappe_HR_Pilot_2026-10-11/Kandil_HR_Pilot_Results.html">${t('Previous HR pilot evidence ↗','أدلة تجربة HR السابقة ↗')}</a></div><div class="stack"><div class="stack-node feature"><strong>${t('قنديل · Company portal','قنديل · بوابة الشركة')}</strong><p>${t('Proposed React + TypeScript · role dashboards, requests, shared inbox, Arabic / English','React + TypeScript مقترح · لوحات حسب الدور وطلبات واعتمادات وعربي / إنجليزي')}</p></div><div class="connector">↓ ↑</div><div class="stack-node"><strong>${t('Custom company API · proposed Django','واجهة خدمات الشركة · Django مقترح')}</strong><p>${t('Identity mapping, scoped access and integrations. Delivery and estimator are modules of one custom application.','ربط الهويات والصلاحيات والتكاملات. التوصيل والتكلفة وحدتان في تطبيق مخصص واحد.')}</p></div><div class="connector">↓ ↑</div><div class="stack-branches"><div class="stack-node"><span class="eyebrow">01 / HR</span><strong>Frappe HR + kandil_hr</strong><p>${t('Recruitment, employee records and HR rules. Python / Frappe + MariaDB. Native administration first.','التوظيف وملفات الموظفين وقواعد HR. Python / Frappe + MariaDB. الشاشات الإدارية الأصلية أولاً.')}</p></div><div class="stack-node"><span class="eyebrow">02 / CUSTOM</span><strong>${t('Delivery + estimator','التوصيل + تقدير التكلفة')}</strong><p>${t('Django + PostgreSQL proposed. Delivery events, estimate revisions and calculation snapshots.','Django + PostgreSQL مقترح. أحداث التوصيل ونسخ التقديرات ونتائج الحساب المحفوظة.')}</p></div><div class="stack-node"><span class="eyebrow">03 / EXISTING</span><strong>Odoo</strong><p>${t('Keep agreed ERP responsibilities. Confirm actual record owners, version, API access and connector scope.','يحتفظ بمسؤوليات ERP المتفق عليها. نؤكد مالك البيانات والإصدار وإتاحة API ونطاق الربط.')}</p></div></div></div><div class="note">${t('Frappe is not Django. The proposed Django backend belongs to the custom company modules; Frappe remains a separate HR service.','Frappe ليس مبنياً على Django. خادم Django المقترح للوحدات المخصصة للشركة؛ ويظل Frappe خدمة HR منفصلة.')}</div><div class="architecture-info"><h2>${t('Ownership before integration','تحديد ملكية البيانات قبل الربط')}</h2>${panel(t('One owner for each record','مصدر واحد لكل سجل'),'',`<div class="table-wrap"><table><thead><tr><th>${t('Record','السجل')}</th><th>${t('Authority','المصدر الأساسي')}</th><th>${t('Portal behavior','دور البوابة')}</th></tr></thead><tbody>${[[t('Employee / recruitment','الموظف / التوظيف'),'Frappe HR',t('Read scoped views; execute validated HR actions.','عرض حسب الصلاحية وتنفيذ إجراءات HR بعد التحقق.')],[t('Order / customer / stock','الأمر / العميل / المخزون'),'Odoo*',t('References and read projections; no duplicate editable master.','مراجع ونسخ للعرض؛ لا سجل أساسي ثانٍ قابل للتعديل.')],[t('Delivery proof / event','إثبات / حدث توصيل'),t('Delivery module','وحدة التوصيل'),t('Capture, review and explicitly reconcile approved outcomes.','تسجيل ومراجعة ومطابقة النتائج المعتمدة صراحة.')],[t('Estimate / cost snapshot','التقدير / نسخة التكلفة'),t('Estimator module','وحدة التكلفة'),t('Versioned quantities, rates and calculations.','إصدارات للكميات والأسعار والحسابات.')],[t('Approval decision','قرار الاعتماد'),t('Owning module','الوحدة المسؤولة'),t('One inbox, with decisions validated in the source system.','صندوق واحد، والقرار يتحقق منه النظام المصدر.')]].map(row=>`<tr>${row.map(c=>`<td>${c}</td>`).join('')}</tr>`).join('')}</tbody></table></div><div class="panel-body small muted">* ${t('Where these workflows are configured. Odoo API entitlement and precise boundaries remain to be verified.','حيث تكون هذه العمليات مفعلة. صلاحية API وحدود مسؤولية Odoo تحتاج التحقق.')}</div>`)}<h2>${t('Build one complete journey at a time','نبني مساراً كاملاً كل مرة')}</h2><div class="panel panel-body stage-list">${[[t('Agree the design and HR rules','اعتماد التصميم وقواعد HR'),t('Review this prototype; HR completes its pilot checklist. Confirm identity and Odoo integration access.','راجع النموذج وأكمل قائمة HR. أكد الهوية وإتاحة الربط مع Odoo.')],[t('Connect portal → recruitment','ربط البوابة ← التوظيف'),t('Real users, multi-site requests, assigned decisions and audited joining. Keep native HR admin screens.','مستخدمون فعليون وطلبات متعددة المواقع وقرارات مخولة ومباشرة موثقة، مع شاشات HR الإدارية.')],[t('Pilot delivery in one branch','تجربة التوصيل بفرع واحد'),t('Confirm dispatch, partial/refused delivery and proof review. Start with an agreed read-only Odoo reference.','أكد الإرسال والتسليم الجزئي والمرفوض ومراجعة الإثبات، وابدأ بمرجع Odoo للقراءة.')],[t('Validate one complete estimate','تحقق من تقدير كامل واحد'),t('Engineer-approved quantity breakdown, rate versions and a reproducible reference case.','حصر كميات معتمد هندسياً وإصدارات أسعار وحالة مرجعية قابلة لإعادة الحساب.')],[t('Prepare controlled production','التجهيز لتشغيل إنتاجي محدود'),t('Migration rehearsal, scoped permissions, backup restore, monitoring, rollback and named owners.','تجربة نقل البيانات ومراجعة الصلاحيات واستعادة النسخ والمراقبة والتراجع ومسؤولون محددون.')]].map(([h,p])=>`<div class="stage-item"><div><h3>${h}</h3><p>${p}</p></div></div>`).join('')}</div><h2>${t('Integration rules','قواعد التكامل')}</h2><div class="grid equal"><div class="panel panel-body"><h3>${t('Failures must stay visible','إظهار حالات الفشل')}</h3><p class="small muted" style="margin-top:12px">${t('Show stale data and failed jobs. Retry idempotent commands and reconcile missed events. Do not claim success when a source system is unavailable.','اظهر البيانات القديمة والمهام الفاشلة. أعد المحاولة دون تكرار الإجراءات وطابق الأحداث المفقودة. لا تعرض نجاحاً عند تعطل النظام المصدر.')}</p></div><div class="panel panel-body"><h3>${t('Identity is a real integration','الهوية تكامل فعلي')}</h3><p class="small muted" style="margin-top:12px">${t('Shared login is proposed. Validate mapped actors and least privilege at every API. Never expose an administrator token in the browser.','تسجيل الدخول الموحد مقترح. تحقق من الهوية والصلاحية في كل API. لا تضع رمز مدير النظام في المتصفح.')}</p></div></div><div class="note amber">${t('No paid tooling is required to view this prototype. Hosting, backups, identity, messaging and Odoo integration costs need a separate operating budget.','لا أدوات مدفوعة لعرض النموذج. الاستضافة والنسخ والهوية والرسائل وربط Odoo تحتاج ميزانية تشغيل منفصلة.')}</div></div>`;}
function openDialog(title,body){$('#dialog').innerHTML=`<div class="dialog-heading"><h2 id="dialog-title">${title}</h2>${button('×','close',`aria-label="${t('Close','إغلاق')}"`)}</div><div class="dialog-body">${body}</div>`;if(!$('#dialog').open)$('#dialog').showModal();}
function showRequest(id){const r=visibleRequests().find(x=>x.id===id);if(!r)return;const can=r.stage===state.role&&r.owner!==state.role;const chain=[...(r.exception?['sector']:[]),...(r.owner==='manager'?[]:['manager']),'hr'];
  const activeIndex=chain.indexOf(r.stage);
  const timeline=chain.map((step,i)=>`<div class="step ${r.stage==='approved'||(activeIndex>=0&&i<activeIndex)?'done':r.stage===step?'current':''}"><div class="dot">${i+1}</div><span>${roleName(step)}</span></div>`).join('');
  openDialog(esc(reqTitle(r)),`<p class="mono">${r.id} · ${t('Synthetic recruitment request','طلب توظيف تجريبي')}</p>${badge(reqStatus(r),r.stage==='rejected'?'red':r.stage==='approved'?'':'amber')}<div class="detail-grid"><div><small>${t('Requester','مقدم الطلب')}</small><strong>${roleName(r.owner)}</strong></div><div><small>${t('Factory A','المصنع أ')}</small><strong>${r.a}</strong></div><div><small>${t('Factory B','المصنع ب')}</small><strong>${r.b}</strong></div></div>${r.note?`<div class="note amber">${esc(r.note)}</div>`:''}<div class="timeline">${timeline}</div>${r.owner==='manager'?`<p class="small muted">${t('Department manager step skipped because the requester holds that role.','تم تخطي اعتماد مدير الإدارة لأنه مقدم الطلب.')}</p>`:''}<h3>${t('Activity','سجل النشاط')}</h3>${r.events.map(e=>`<div class="audit-row">${esc(Array.isArray(e)?t(...e):e)}</div>`).join('')}${can?`<div class="note">${t('Review the scope before deciding. This action changes the demo only.','راجع نطاق الطلب قبل اتخاذ القرار. الإجراء يغير المثال فقط.')}</div><label class="field">${t('Decision note (required for rejection)','ملاحظة القرار (مطلوبة للرفض)')}<textarea id="decision-note" maxlength="500"></textarea></label><div id="decision-error" class="error" role="alert"></div><div class="form-actions">${button(t('Reject','رفض'),'decide',`data-id="${r.id}" data-decision="reject"`,'danger')}${button(t('Approve this step','اعتماد هذه الخطوة'),'decide',`data-id="${r.id}" data-decision="approve"`,'primary')}</div>`:`<div class="note">${t('This role has no decision at the current step.','الدور الحالي لا يملك قراراً في هذه الخطوة.')}</div>`}`);
}
function newRequest(){if(!['employee','manager'].includes(state.role))return;openDialog(t('New hiring request','طلب توظيف جديد'),`<p>${t('One request can include several locations. This demo uses fictional availability of 3 at Factory A and 2 at Factory B. It is a form example, not the live capacity ledger.','يمكن أن يشمل الطلب عدة مواقع. المثال يستخدم إتاحة افتراضية ٣ بالمصنع أ و٢ بالمصنع ب. هذا نموذج إدخال وليس سجل الطاقة الفعلي.')}</p><form id="request-form"><div class="field-grid"><label class="field full">${t('Job title','المسمى الوظيفي')}<input name="title" required maxlength="100" placeholder="${t('e.g. Assembly technician','مثال: فني تجميع')}"></label><label class="field">${t('Factory A · available 3','المصنع أ · المتاح ٣')}<input type="number" name="a" value="1" min="0" max="100" step="1" required></label><label class="field">${t('Factory B · available 2','المصنع ب · المتاح ٢')}<input type="number" name="b" value="0" min="0" max="100" step="1" required></label><label class="field full">${t('Reason / capacity exception justification','السبب / مبرر استثناء العدد')}<textarea name="reason" maxlength="500" placeholder="${t('Required when either location exceeds availability','مطلوب إذا تجاوز عدد أي موقع المتاح')}"></textarea></label></div><div class="error" id="request-error" role="alert"></div><div class="form-actions">${button(t('Cancel','إلغاء'),'close','type="button"')}<button class="primary" type="submit">${t('Submit demo request','إرسال الطلب التجريبي')}</button></div></form>`);}
function showDelivery(){const steps=[t('Scheduled','مجدول'),t('Dispatched','تم الإرسال'),t('Arrived','وصل'),t('Proof review','مراجعة الإثبات'),t('Completed','مكتمل')];const editable=state.role==='operations';openDialog(t('DL-028 · Cairo handover','DL-028 · تسليم القاهرة'),`<p>${t('Sample order SO-DEMO-028 · 8 packages · fictional route. No real tracking or Odoo write.','أمر تجريبي SO-DEMO-028 · ٨ طرود · مسار افتراضي. لا تتبع فعلي أو كتابة في Odoo.')}</p><div class="timeline">${steps.map((s,i)=>`<div class="step ${i<state.deliveryStep?'done':i===state.deliveryStep?'current':''}"><div class="dot">${i<state.deliveryStep?'✓':i+1}</div><span>${s}</span></div>`).join('')}</div><div class="detail-grid"><div><small>${t('Origin','المصدر')}</small><strong>${t('Sample warehouse','مخزن تجريبي')}</strong></div><div><small>${t('Destination','الوجهة')}</small><strong>${t('Cairo · sample receiver','القاهرة · مستلم تجريبي')}</strong></div><div><small>${t('Outcome','النتيجة')}</small><strong>${state.deliveryOutcome?t('Exception — review needed','استثناء — يحتاج مراجعة'):steps[state.deliveryStep]}</strong></div></div>${state.deliveryNote?`<div class="note">${esc(state.deliveryNote)}</div>`:''}${state.deliveryStep===3?`<div class="note">${t('Synthetic proof reference: POD-DEMO-028. In production an authorized reviewer must inspect the actual proof and verify quantity/outcome.','مرجع إثبات افتراضي: POD-DEMO-028. في الإنتاج يراجع شخص مخول الإثبات الفعلي والكمية والنتيجة.')}</div>`:''}${editable&&state.deliveryStep<4&&!state.deliveryOutcome?`<label class="field">${t('Handover / exception note','ملاحظة التسليم / الاستثناء')}<textarea id="delivery-note" maxlength="300" placeholder="${t('Required before progressing or recording an exception','مطلوبة قبل التقدم أو تسجيل استثناء')}"></textarea></label><div class="error" id="delivery-error" role="alert"></div><div class="form-actions">${button(t('Record exception','تسجيل استثناء'),'delivery-exception','','danger')}${button(state.deliveryStep===2?t('Capture sample proof','تسجيل إثبات تجريبي'):t('Confirm reviewed outcome','تأكيد النتيجة بعد المراجعة'),'delivery-advance','','primary')}</div>`:`<div class="note">${state.deliveryOutcome?t('Paused for dispatcher review. Rescheduling and partial-return workflows need operations definition.','موقوف للمراجعة. إعادة الجدولة والتسليم الجزئي والمرتجعات تحتاج تعريف العمليات.'):t('Read-only view. A real Odoo stock update would be a separate authorized action.','عرض للقراءة. تحديث مخزون Odoo الفعلي إجراء مخول منفصل.')}</div>`}`);}
function cairoDate(){return new Intl.DateTimeFormat('en-GB',{timeZone:'Africa/Cairo',day:'2-digit',month:'2-digit',year:'numeric'}).format(new Date());}
function showLetter(){openDialog(t('Employment letter · sample','خطاب جهة العمل · نموذج'),`<p>${t('This sample is not a signed or valid employment certificate. Real issuance needs identity, template and approval rules.','هذا نموذج غير موقع وغير صالح كشهادة عمل. الإصدار الفعلي يتطلب الهوية والنموذج وقواعد الاعتماد.')}</p><div class="panel panel-body"><div class="eyebrow">${t('SAMPLE ONLY','نموذج فقط')}</div><h3>قنديل</h3><p style="margin-top:15px">${t('Employee: Example employee','الموظف: موظف تجريبي')}</p><p>${t('Generation date','تاريخ الإصدار')}: <b>${cairoDate()}</b> (Cairo)</p><p class="small muted">${t('No real employment or salary data included.','لا توجد بيانات توظيف أو راتب فعلية.')}</p></div><div class="note">${t('A new generation uses today’s date. An archived issued version keeps its original date. The downloaded text is labeled SAMPLE.','الإصدار الجديد بتاريخ اليوم؛ النسخة المؤرشفة تحتفظ بتاريخ إصدارها. الملف يحمل عبارة نموذج تجريبي.')}</div><div class="form-actions">${button(t('Download sample text','تنزيل نموذج نصي'),'download-letter','','primary')}</div>`);}
document.addEventListener('click',ev=>{
  const el=ev.target.closest('[data-action]');if(!el)return;const a=el.dataset.action;
  if(a==='nav')navTo(el.dataset.page);
  else if(a==='language'){state.lang=state.lang==='en'?'ar':'en';$('#dialog').close();render();}
  else if(a==='menu')document.body.classList.toggle('menu-open');
  else if(a==='close')$('#dialog').close();
  else if(a==='filter'){state.filter=el.dataset.value;render();}
  else if(a==='reset'){const {lang,role,page}=state;state={...initialState(),lang,role,page};$('#dialog').close();render();toast(t('Demo reset. No external records were changed.','تمت إعادة التجربة. لم تتغير أي سجلات خارجية.'));}
  else if(a==='new-request')newRequest();
  else if(a==='request')showRequest(el.dataset.id);
  else if(a==='decide'){
    const r=state.requests.find(x=>x.id===el.dataset.id);if(!r||r.stage!==state.role||r.owner===state.role)return;
    const note=$('#decision-note').value.trim();if(el.dataset.decision==='reject'&&!note){$('#decision-error').textContent=t('Add a reason before rejecting.','أضف سبباً قبل الرفض.');return;}
    const rejecting=el.dataset.decision==='reject';r.events.push(`${roleName()}: ${rejecting?t('Rejected','رفض'):t('Approved','اعتماد')}${note?' · '+note:''}`);
    r.stage=rejecting?'rejected':r.stage==='sector'?(r.owner==='manager'?'hr':'manager'):r.stage==='manager'?'hr':'approved';
    $('#dialog').close();render();toast(t('Demo decision recorded.','تم تسجيل القرار التجريبي.'));
  }
  else if(a==='delivery-detail')showDelivery();
  else if(a==='delivery-advance'||a==='delivery-exception'){
    if(state.role!=='operations'||state.deliveryStep>=4||state.deliveryOutcome)return;
    const note=$('#delivery-note').value.trim();if(!note){$('#delivery-error').textContent=t('A note is required.','الملاحظة مطلوبة.');return;}
    state.deliveryNote=note;if(a==='delivery-exception')state.deliveryOutcome='exception';else state.deliveryStep++;
    render();showDelivery();toast(t('Demo milestone recorded. No Odoo update.','تم تسجيل المرحلة التجريبية دون تحديث Odoo.'));
  }
  else if(a==='review-estimate'){
    if(state.role!=='estimator')return;
    if(!$('#estimate-form').reportValidity())return;
    const form=new FormData($('#estimate-form'));let changed=false;
    for(const k of ['qty','rate','waste','labor','outside','overhead'])if(Number(form.get(k))!==state.estimate[k])changed=true;
    if(changed){toast(t('Recalculate changed inputs before reviewing.','أعد حساب المدخلات المعدلة قبل المراجعة.'));return;}
    state.estimateReviewed=true;render();toast(t('Review confirmed for these demo inputs.','تم تأكيد مراجعة هذه المدخلات التجريبية.'));
  }
  else if(a==='save-estimate'){
    if(state.role!=='estimator'||!state.estimateReviewed)return;
    const form=new FormData($('#estimate-form'));
    if(['qty','rate','waste','labor','outside','overhead'].some(k=>Number(form.get(k))!==state.estimate[k])){toast(t('Inputs changed. Recalculate and review first.','تغيرت المدخلات. أعد الحساب والمراجعة أولاً.'));return;}
    if(state.estimateSaved){toast(t('The first snapshot is preserved. Reset the demo to try another.','تم الاحتفاظ بالنسخة الأولى. أعد التجربة لتجربة نسخة أخرى.'));return;}
    state.estimateSaved={inputs:{...state.estimate},...costs()};render();toast(t('Fixed demo snapshot saved in this tab.','حُفظت نسخة تجريبية ثابتة داخل الصفحة.'));
  }
  else if(a==='letter')showLetter();
  else if(a==='download-letter'){
    const blob=new Blob([`SAMPLE ONLY / نموذج تجريبي فقط\nقنديل — Employment letter design sample\nEmployee: Example employee / موظف تجريبي\nGeneration date (Africa/Cairo): ${cairoDate()}\nNo real employment, salary, signature or approval.\n`],{type:'text/plain;charset=utf-8'});
    const url=URL.createObjectURL(blob),link=document.createElement('a');link.href=url;link.download='Kandil_SAMPLE_letter.txt';link.click();setTimeout(()=>URL.revokeObjectURL(url),1000);toast(t('Sample text downloaded with today’s Cairo date.','تم تنزيل النموذج النصي بتاريخ اليوم في القاهرة.'));
  }
});
document.addEventListener('change',ev=>{if(ev.target.id==='role'){state.role=ev.target.value;state.filter='all';$('#dialog').close();render();}});
document.addEventListener('submit',ev=>{
  if(ev.target.id==='request-form'){
    ev.preventDefault();if(!['employee','manager'].includes(state.role))return;
    const data=new FormData(ev.target),a=Number(data.get('a')),b=Number(data.get('b')),title=String(data.get('title')).trim(),note=String(data.get('reason')).trim();
    if(!title||!Number.isInteger(a)||!Number.isInteger(b)||a<0||b<0||a>100||b>100||a+b<1){$('#request-error').textContent=t('Enter a title and at least one whole-number position.','أدخل المسمى وعدداً صحيحاً لوظيفة واحدة على الأقل.');return;}
    const exception=a>3||b>2;if(exception&&!note){$('#request-error').textContent=t('A capacity exception requires a justification.','استثناء العدد يحتاج مبرراً.');return;}
    const r={id:'HR-'+(105+state.requests.length-3),title,owner:state.role,a,b,note,exception,stage:exception?'sector':state.role==='manager'?'hr':'manager',events:[['Demo request submitted','تم إرسال الطلب التجريبي']]};
    state.requests.unshift(r);$('#dialog').close();state.page='hr';render();toast(t('Demo request submitted to the next approver.','تم إرسال الطلب التجريبي للمعتمد التالي.'));
  }
  if(ev.target.id==='estimate-form'){
    ev.preventDefault();if(state.role!=='estimator')return;const data=new FormData(ev.target);
    for(const k of ['qty','rate','waste','labor','outside','overhead']){const n=Number(data.get(k));if(!Number.isFinite(n)||n<0)return;state.estimate[k]=n;}
    state.estimateReviewed=false;render();toast(t('Cost recalculated. Quantity and rate review is required again.','أُعيد الحساب. مراجعة الكميات والأسعار مطلوبة مجدداً.'));
  }
});
render();
